SELECT
a.*
FROM
b_marketing_data_clean_general_config a
WHERE
a.is_del = 1

    AND a.api_code = #{apiCode,jdbcType=VARCHAR}


    AND a.account_type = #{accountType,jdbcType=VARCHAR}


    AND a.accept_type = #{acceptType,jdbcType=INTEGER}


    AND a.status = #{status}


    AND a.sftp_path = #{sftpPath}

ORDER BY a.update_time DESC

SELECT
COUNT(1)
FROM
b_marketing_data_clean_general_config a
WHERE
a.is_del = 1

    AND a.api_code = #{apiCode,jdbcType=VARCHAR}


    AND a.account_type = #{accountType,jdbcType=VARCHAR}


    AND a.accept_type = #{acceptType,jdbcType=INTEGER}

select * from b_marketing_data_clean_general_config config where data_type = 0 and accept_type =1 and custom_run_status =0 and is_del = 1 and status =1
and config.api_code = #{apiCode}
order by config.update_time desc
